import { open, readdir } from "node:fs/promises";
import path from "node:path";

export interface FareSnapshot {
  supplier: string;
  generatedAt: string;
  fares: Array<{ route: string; cabin: string; amountMinor: number; currency: string }>;
}

export class SnapshotTooLargeError extends Error {
  constructor(readonly file: string, readonly size: number) {
    super(`fare snapshot ${file} is ${size} bytes`);
    this.name = "SnapshotTooLargeError";
  }
}

const MAX_SNAPSHOT_BYTES = 8 * 1024 * 1024;

export async function readSnapshot(file: string): Promise<FareSnapshot> {
  const handle = await open(file, "r");
  const { size } = await handle.stat();
  if (size > MAX_SNAPSHOT_BYTES) {
    throw new SnapshotTooLargeError(file, size);
  }
  try {
    const buf = Buffer.alloc(size);
    let offset = 0;
    while (offset < size) {
      const { bytesRead } = await handle.read(buf, offset, size - offset, offset);
      if (bytesRead === 0) break;
      offset += bytesRead;
    }
    return JSON.parse(buf.subarray(0, offset).toString("utf8")) as FareSnapshot;
  } finally {
    await handle.close();
  }
}

export async function listSnapshotFiles(dir: string): Promise<string[]> {
  const entries = await readdir(dir, { withFileTypes: true });
  return entries
    .filter((e) => e.isFile() && e.name.endsWith(".fares.json"))
    .map((e) => path.join(dir, e.name))
    .sort();
}

import { listSnapshotFiles, readSnapshot, FareSnapshot, SnapshotTooLargeError } from "./snapshotReader";

export interface Logger {
  info(msg: string, fields?: Record<string, unknown>): void;
  warn(msg: string, fields?: Record<string, unknown>): void;
}

export interface FareIndex {
  replaceSupplier(supplier: string, fares: FareSnapshot["fares"], generatedAt: string): void;
}

export interface LoadResult {
  loaded: number;
  skipped: string[];
}

export class FareSnapshotLoader {
  private running = false;

  constructor(
    private readonly dir: string,
    private readonly index: FareIndex,
    private readonly log: Logger,
  ) {}

  async loadAll(): Promise<LoadResult> {
    if (this.running) {
      this.log.info("fare snapshot load already in progress");
      return { loaded: 0, skipped: [] };
    }
    this.running = true;
    const result: LoadResult = { loaded: 0, skipped: [] };
    try {
      const files = await listSnapshotFiles(this.dir);
      for (const file of files) {
        try {
          const snap = await readSnapshot(file);
          this.index.replaceSupplier(snap.supplier, snap.fares, snap.generatedAt);
          result.loaded++;
        } catch (err) {
          if (err instanceof SnapshotTooLargeError) {
            this.log.warn("skipping oversized fare snapshot", { file, size: err.size });
          } else {
            this.log.warn("failed to load fare snapshot", { file, error: String(err) });
          }
          result.skipped.push(file);
        }
      }
      this.log.info("fare snapshots loaded", { ...result, skipped: result.skipped.length });
      return result;
    } finally {
      this.running = false;
    }
  }

  startPolling(intervalMs: number): () => void {
    const timer = setInterval(() => {
      void this.loadAll();
    }, intervalMs);
    timer.unref();
    return () => clearInterval(timer);
  }
}

